/**
 * Node-RED DMS API Client
 * 提供與 DMS API 的整合，包含簽名機制
 */

(function() {
    // 取得環境變數
    const secretKey = 'da6e6728-b51c-11ea-ac59-00ff7ae2c9c8';
    const requester = 'admin';

    // API Base URL - 可以從 settings 取得或使用預設值
    const baseUrl = RED.settings.dmsApiEndpoint || 'http://101.35.85.65:8082';

    // 取得用戶 token
    function getUserToken() {
        return localStorage.getItem('token') || '';
    }

    // 建立一個方法來呼叫簽名 API
    async function getSignData({ url, method, params, data }) {
        try {
            const userToken = getUserToken();
            const response = await fetch(`${baseUrl}/schideron/openApi/auth/sign`, {
                method: 'POST',
                headers: {
                    'Authorization': `Bearer ${userToken}`,
                    'Content-Type': 'application/json;charset=utf-8',
                    'secretKey': secretKey
                },
                body: JSON.stringify({
                    requester,
                    url,
                    method,
                    params
                })
            });

            const result = await response.json();

            if ([1005, 1006].includes(result.code)) {
                console.log('sign api response.data.code === 1005 or 1006');
                // 登出，清除token
                localStorage.removeItem('token');
                window.location.href = '/';
                throw new Error(result.message);
            }
            return result; // 預期返回 { sign, t }
        } catch (error) {
            console.error('Sign API error:', error);
            throw error;
        }
    }

    // 建立通用的 API 請求方法
    async function request(url, options = {}) {
        const method = (options.method || 'GET').toUpperCase();
        const relativeUrl = url.startsWith('http') ?
            new URL(url).pathname.split('?')[0] :
            url.split('?')[0];

        // 收集參數
        let currentParams = { ...options.params };

        // 如果是 POST/PUT/PATCH，合併 body 的 JSON
        if (['POST', 'PUT', 'PATCH'].includes(method) && options.body) {
            try {
                const bodyData = typeof options.body === 'string' ?
                    JSON.parse(options.body) :
                    options.body;
                currentParams = {
                    ...currentParams,
                    ...bodyData
                };
            } catch (e) {
                console.warn('Failed to parse request body:', e);
            }
        }

        // 準備 headers
        const headers = {
            'Content-Type': 'application/json',
            'secretKey': secretKey,
            ...(options.headers || {})
        };

        // 非登入請求需要簽名
        if (relativeUrl !== '/schideron/openApi/auth/login') {
            const signData = await getSignData({
                url: relativeUrl,
                method,
                params: { ...currentParams, requester },
                data: options.body
            });

            headers['sign'] = signData.sign;
            headers['t'] = signData.t;

            const userToken = getUserToken();
            headers['authorization'] = `Bearer ${userToken}`;
        }

        // 發送請求
        let fullUrl = url.startsWith('http') ? url : `${baseUrl}${url}`;

        // GET 和 DELETE 請求需要將參數添加到 URL
        if (['GET', 'DELETE'].includes(method)) {
            const queryParams = { ...currentParams, requester };
            const queryString = new URLSearchParams(queryParams).toString();
            if (queryString) {
                fullUrl += (fullUrl.includes('?') ? '&' : '?') + queryString;
            }
        }

        // 準備 request body，POST/PUT/PATCH 需要包含 requester
        let requestBody;
        if (!['GET', 'DELETE'].includes(method) && options.body) {
            const bodyData = typeof options.body === 'string' ? JSON.parse(options.body) : options.body;
            requestBody = JSON.stringify({ ...bodyData, requester });
        }

        const response = await fetch(fullUrl, {
            method,
            headers,
            body: requestBody
        });

        const result = await response.json();

        // 檢查回應狀態
        if (response.status === 401) {
            console.log('Unauthorized');
            localStorage.removeItem('token');
            window.location.href = '/';
            throw new Error('Unauthorized');
        }

        if (result.status !== 'SUCCESS') {
            throw new Error(result.message || 'Error');
        }

        return result;
    }

    // 導出 API 模組
    window.DMSAPI = {
        baseUrl,
        requester,
        getUserToken,
        request,

        // GET 請求
        get: function(url, params) {
            return request(url, { method: 'GET', params });
        },

        // POST 請求
        post: function(url, body, params) {
            return request(url, { method: 'POST', body, params });
        },

        // PUT 請求
        put: function(url, body, params) {
            return request(url, { method: 'PUT', body, params });
        },

        // DELETE 請求
        delete: function(url, params) {
            return request(url, { method: 'DELETE', params });
        }
    };

    console.log('DMS API Client initialized');
})();
